// ============================================================
// Unroll Attachments & Normalize          (Run Once for All Items)
//
// One output item per processable unit:
//   - one item per PDF attachment, OR
//   - one item per unsupported attachment (when the mail has no PDF), OR
//   - one item for the email body (when nothing is attached)
//
// Every piece of metadata a later node needs is carried ON THE ITEM.
// No $getWorkflowStaticData - that was the source of the empty
// "Gmail Message ID" that made the Add Label node fail.
// ============================================================

// ---- triage guard ------------------------------------------
// Belt-and-braces backstop to the "-label:novus-not-invoice" term in the
// Gmail search. If a mail somehow arrives here still carrying the
// not-an-invoice label, drop it now - before any paid node.
// Put your Gmail label ID here (Label_xxxxxxxx). Leave as-is to disable.
const NOT_INVOICE_LABEL_ID = 'Label_REPLACE_WITH_NOT_INVOICE_LABEL_ID';

function alreadyTriaged(email) {
  if (!NOT_INVOICE_LABEL_ID || NOT_INVOICE_LABEL_ID.indexOf('REPLACE') !== -1) return false;
  const ids = email.labelIds || email.labels || [];
  if (!Array.isArray(ids)) return false;
  return ids.some(function (l) {
    return (typeof l === 'string' ? l : (l && l.id)) === NOT_INVOICE_LABEL_ID;
  });
}

const PDF_EXT = /\.pdf$/i;
const DOC_EXT = /\.(docx?|xlsx?|pptx?|csv|txt|rtf|odt|ods|pages|numbers|zip|rar|7z|eml|msg|html?)$/i;
const IMG_EXT = /\.(png|jpe?g|gif|tiff?|bmp|webp|heic|avif)$/i;

function senderOf(email) {
  const raw = email.From || email.from || '';
  if (typeof raw === 'string' && raw.trim()) {
    const m = raw.match(/<([^>]+)>/);
    return (m ? m[1] : raw).trim().toLowerCase();
  }
  if (raw && Array.isArray(raw.value) && raw.value[0]) {
    return String(raw.value[0].address || '').trim().toLowerCase();
  }
  if (raw && raw.text) {
    const m = String(raw.text).match(/<([^>]+)>/);
    return (m ? m[1] : raw.text).trim().toLowerCase();
  }
  return '';
}

const out = [];
const emails = $input.all();

for (let i = 0; i < emails.length; i++) {
  const email = emails[i].json || {};
  const binaries = emails[i].binary || {};

  // Guard against empty dummy items produced on repeat runs when 0 emails exist
  const hasId = Boolean(email.id || email.messageId);
  const hasBody = Boolean(email.textPlain || email.text || email.snippet || email.Snippet);
  const hasSubject = Boolean(email.Subject || email.subject);
  const hasBinaries = Object.keys(binaries).length > 0;

  if (!hasId && !hasBody && !hasSubject && !hasBinaries) {
    continue;
  }

  if (alreadyTriaged(email)) continue;   // <- already reviewed, do not pay for it again

  const base = {
    gmail_message_id: email.id || email.messageId || '',
    gmail_thread_id: email.threadId || '',
    sender_email: senderOf(email) || 'unknown@unknown',
    subject: String(email.Subject || email.subject || ''),
    plain_text_body: String(email.textPlain || email.text || email.snippet || email.Snippet || ''),
    received_at: email.internalDate
      ? new Date(Number(email.internalDate)).toISOString()
      : String(email.date || email.Date || ''),
  };

  // ---- classify every binary on this email ------------------
  const pdfs = [];
  const unsupported = [];

  for (const key of Object.keys(binaries)) {
    const f = binaries[key] || {};
    const name = String(f.fileName || '');
    const mime = String(f.mimeType || '').toLowerCase();

    if (mime.includes('pdf') || PDF_EXT.test(name)) {
      pdfs.push({ key: key, f: f, name: name || key + '.pdf', mime: mime });
    } else if (DOC_EXT.test(name) || (name && IMG_EXT.test(name))) {
      unsupported.push({ key: key, f: f, name: name, mime: mime });
    }
    // inline images with no filename (signature logos) are ignored on purpose
  }

  // ---- emit --------------------------------------------------
  if (pdfs.length > 0) {
    pdfs.forEach(function (p, idx) {
      out.push({
        json: Object.assign({}, base, {
          has_attachment: true,
          attachment_key: p.key,
          attachment_index: idx,
          total_attachments: pdfs.length,
          attachment_filename: p.name,
          attachment_mime: p.mime || 'application/pdf',
          source_type: 'pdf_attachment',
          route_source: 'pdf',
          extraction_error: '',
        }),
        binary: { data: p.f },
        pairedItem: i,
      });
    });
  } else if (unsupported.length > 0) {
    unsupported.forEach(function (u, idx) {
      out.push({
        json: Object.assign({}, base, {
          has_attachment: true,
          attachment_key: u.key,
          attachment_index: idx,
          total_attachments: unsupported.length,
          attachment_filename: u.name,
          attachment_mime: u.mime,
          source_type: 'pdf_attachment',
          route_source: 'unsupported',
          extraction_error: 'Unsupported attachment type (' + (u.mime || 'unknown type') + '): ' + u.name,
        }),
        binary: { data: u.f },
        pairedItem: i,
      });
    });
  } else {
    out.push({
      json: Object.assign({}, base, {
        has_attachment: false,
        attachment_key: null,
        attachment_index: 0,
        total_attachments: 0,
        attachment_filename: '',
        attachment_mime: '',
        source_type: 'email_body',
        route_source: 'email_body',
        extraction_error: '',
      }),
      pairedItem: i,
    });
  }
}

return out;

// ============================================================
// Inspect Text Layer & Classify           (Run Once for ALL Items)
//
// Runs in All Items mode because .all() and .itemMatching() do not
// exist in Run Once for Each Item mode.
//
// Sets $json.route to exactly one of:
//   'text'       - a real text layer we can hand to the extractor
//   'ocr'        - extraction "succeeded" but returned nothing usable
//                  (image-only page, browser print furniture, ...)
//   'unreadable' - Extract From File threw (corrupt / encrypted / not a PDF)
// ============================================================

// Only route_source === 'pdf' items were sent into Extract From PDF File,
// and the node preserves order 1:1, so index i here IS pdfMetas[i].
const pdfMetas = $('Unroll Attachments & Normalize')
  .all()
  .filter(function (it) { return it.json.route_source === 'pdf'; });

// --- strip everything that is page furniture, not invoice content ---
// This is the fix for the "scanned PDF that still returns a line of text"
// case. A page exported from a browser image viewer yields e.g.
//   7/28/25, 4:53 PM  real-estate-commission-invoice-template.webp (620x877)
//   https://.../real-estate-commission-invoice-template.webp   1/1
// Every token there is furniture. Once it is removed nothing remains,
// so the page has no text layer and must go to OCR.
const ARTEFACTS = [
  /https?:\/\/\S+/gi,                                                      // URLs
  /\b[\w.\-]+\.(webp|png|jpe?g|gif|tiff?|bmp|svg|heic|avif)\b/gi,          // image filenames
  /\(\s*\d{2,5}\s*[×✕xX]\s*\d{2,5}\s*\)/g,                       // (620x877)
  /\b\d{1,2}\/\d{1,2}\/\d{2,4},?\s*\d{1,2}:\d{2}(:\d{2})?\s*(AM|PM)?\b/gi, // print timestamp
  /\bpage\s*\d+\s*(of\s*\d+)?\b/gi,                                        // Page 1 of 1
  /^\s*\d{1,3}\s*\/\s*\d{1,3}\s*$/gm,                                      // 1/1 page marker
  /[\uFFFD\u0000-\u001F]/g,                                                // replacement / control chars
];

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};

  // --- recover the metadata that entered Extract From PDF File ---
  let meta = (pdfMetas[i] && pdfMetas[i].json) || null;
  if (!meta) {
    try { meta = $('Unroll Attachments & Normalize').itemMatching(i).json; } catch (e) { meta = {}; }
  }

  // --- did the extractor fail? (On Error = Continue keeps the item) ---
  let errMsg = '';
  if (j.error) {
    errMsg = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
  } else if (j.errorMessage) {
    errMsg = String(j.errorMessage);
  } else if (typeof j.text !== 'string' && j.message) {
    errMsg = String(j.message);
  }

  const rawText = typeof j.text === 'string' ? j.text : '';

  if (errMsg && !rawText.trim()) {
    out.push({
      json: Object.assign({}, meta, {
        source_type: 'pdf_attachment',
        invoice_text: '',
        extracted_chars: 0,
        route: 'unreadable',
        failure_reason: 'corrupt_pdf',
        extraction_error: 'PDF could not be parsed: ' + errMsg.slice(0, 250),
      }),
    });
    continue;
  }

  let stripped = rawText.replace(/\r/g, ' ');
  for (const p of ARTEFACTS) stripped = stripped.replace(p, ' ');
  stripped = stripped.replace(/\s+/g, ' ').trim();

  const meaningfulChars = stripped.replace(/[^a-zA-Z0-9]/g, '').length;
  const letters = stripped.replace(/[^a-zA-Z]/g, '').length;
  const hasDigits = /\d/.test(stripped);
  const invoiceSignal = /(invoice|factuur|facture|rechnung|fattura|factura|bill|statement|fee note|amount due|total|subtotal|balance|vat|tax|due date|payment|remit|quantity|qty)/i.test(stripped);

  const needsOcr =
    meaningfulChars < 60 ||
    letters < 30 ||
    !hasDigits ||
    (!invoiceSignal && meaningfulChars < 250);

  if (needsOcr) {
    const why = meaningfulChars < 60
      ? 'no usable text layer after stripping page artefacts (' + meaningfulChars + ' meaningful characters left)'
      : (!hasDigits ? 'text layer contains no numeric data'
                    : 'text layer contains no invoice vocabulary');
    out.push({
      json: Object.assign({}, meta, {
        source_type: 'pdf_attachment',
        invoice_text: '',
        raw_text_preview: rawText.slice(0, 300),
        extracted_chars: rawText.trim().length,
        meaningful_chars: meaningfulChars,
        route: 'ocr',
        failure_reason: 'no_text_layer',
        extraction_error: 'Image-only PDF: ' + why,
      }),
    });
    continue;
  }

  out.push({
    json: Object.assign({}, meta, {
      source_type: 'pdf_attachment',
      invoice_text: rawText.trim(),
      extracted_chars: rawText.trim().length,
      meaningful_chars: meaningfulChars,
      pdf_page_count: j.numpages || null,
      route: 'text',
      failure_reason: '',
      extraction_error: '',
    }),
  });
}

return out;

// ============================================================
// Prepare Non-PDF Source                  (Run Once for Each Item)
//
// Handles both remaining source types:
//   route_source = 'email_body'  -> read the body
//   route_source = 'unsupported' -> a .docx/.xlsx/.jpg was attached;
//                                   fail cleanly, do not call Claude
// Metadata is already on the item, so nothing has to be looked up.
// ============================================================
const meta = $json;

if (meta.route_source === 'unsupported') {
  return {
    json: Object.assign({}, meta, {
      invoice_text: '',
      extracted_chars: 0,
      route: 'unreadable',
      failure_reason: 'unsupported_attachment',
      extraction_error: meta.extraction_error || 'Unsupported attachment type',
    }),
  };
}

const body = String(meta.plain_text_body || '').trim();
const meaningful = body.replace(/[^a-zA-Z0-9]/g, '').length;

if (meaningful < 25) {
  return {
    json: Object.assign({}, meta, {
      source_type: 'email_body',
      invoice_text: '',
      extracted_chars: body.length,
      route: 'unreadable',
      failure_reason: 'empty_email_body',
      extraction_error: 'Email has no attachment and no readable body text',
    }),
  };
}

return {
  json: Object.assign({}, meta, {
    source_type: 'email_body',
    invoice_text: body,
    extracted_chars: body.length,
    meaningful_chars: meaningful,
    route: 'text',
    failure_reason: '',
    extraction_error: '',
  }),
};

// ============================================================
// Re-attach PDF Binary                    (Run Once for ALL Items)
//
// All Items mode because .all() is not available per-item.
//
// Extract From File drops the binary, so pull the original PDF back
// off the Unroll node, matched deterministically on
// gmail_message_id + attachment_key.
// Also carries the OCR system prompt so BOTH OCR HTTP nodes
// (Claude and Nemotron) read their instructions from one place.
// ============================================================
const OCR_SYSTEM_PROMPT = "You are reading a scanned invoice for Novus Realty, a property management company. The PDF has no text layer, so you must read the page visually.\n\nOUTPUT CONTRACT - this overrides any habit you have of describing a document in your own structure.\n\nReturn ONE flat JSON object and nothing else. No prose. No markdown fence. It must contain EXACTLY these twelve keys and no others:\n\nreadable, unreadable_reason, is_invoice, not_invoice_reason, vendor_name, invoice_number, invoice_date, due_date, total_amount, currency, description, is_credit_note\n\nDo NOT nest objects. Do NOT add keys such as from, bill_to, ship_to, line_items, subtotal, sales_tax, amount_paid, balance_due, payment_instructions or notes. Anything outside the twelve keys is discarded.\n\nExample of a correct reply:\n{\"readable\": true, \"unreadable_reason\": null, \"is_invoice\": true, \"not_invoice_reason\": null, \"vendor_name\": \"Fairway Commissions\", \"invoice_number\": \"FC-99120\", \"invoice_date\": \"2026-08-15\", \"due_date\": \"2026-09-15\", \"total_amount\": 3450.00, \"currency\": \"USD\", \"description\": \"Commission statement for Q3 property settlements\", \"is_credit_note\": false}\n\nField rules:\n- readable: false if the page is too blurry, cropped, blank or damaged to read with confidence. Then give a short unreadable_reason and leave every other field null. Do not guess at a damaged page.\n- is_invoice: false for anything that is not an actual demand for payment. Then give a short not_invoice_reason.\n- vendor_name: the party ISSUING the invoice, the one to be paid. This is the letterhead or \"From\" party. It is never the \"Bill To\", \"Ship To\" or customer party, and never Novus Realty.\n- invoice_number: exactly as printed on the page. BLANK BEATS INVENTED - if the page carries no invoice number, return null. Never take it from a filename, a heading, a PO number or an account number.\n- invoice_date / due_date: ISO YYYY-MM-DD.\n- total_amount: the single final amount payable, as a plain number with no currency symbol and no thousands separator. Read it from the line labelled Total, Total Due, Amount Due or Balance Due. Never return a line-item rate or a subtotal here.\n- currency: 3-letter ISO code.\n- description: ONE short line summarising what is being billed. Not a list, not an object.\n- Any field you cannot clearly read on the page must be null.";

const src = $('Unroll Attachments & Normalize').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};

  let hit = src.find(function (it) {
    return it.json.gmail_message_id === j.gmail_message_id &&
           it.json.attachment_key === j.attachment_key;
  });

  if (!hit) {
    try { hit = $('Unroll Attachments & Normalize').itemMatching(i); } catch (e) { hit = null; }
  }

  if (!hit || !hit.binary || !hit.binary.data) {
    // never throw - route it to the clean-failure path instead
    out.push({
      json: Object.assign({}, j, {
        route: 'unreadable',
        failure_reason: 'binary_lost',
        extraction_error: 'Could not recover the PDF binary for OCR',
        ocr_system_prompt: OCR_SYSTEM_PROMPT,
        ocr_skipped: true,
      }),
    });
    continue;
  }

  out.push({
    json: Object.assign({}, j, { ocr_system_prompt: OCR_SYSTEM_PROMPT, ocr_skipped: false }),
    binary: { data: hit.binary.data },
  });
}

return out;

// ============================================================
// Standardize OCR Result                  (Run Once for ALL Items)
//
// Metadata comes from Re-attach PDF Binary, NOT from PDF to Base64.
// Extract From File (Move File to Base64 String) REPLACES the item json
// with a fresh object holding only the base64, so reading metadata off
// it produced blank gmail_message_id / sender / filename - which in turn
// left the row with no duplicate key and no id to mark read.
// Re-attach PDF Binary is 1:1 and order-preserving with PDF to Base64.
// ============================================================
const metas = $('Re-attach PDF Binary').all();

const num = function (v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const str = function (v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  return (s === '' || /^(null|n\/a|none|unknown|not specified|not stated|not provided)$/i.test(s)) ? '' : s;
};
const parseLoose = function (t) {
  const fenced = String(t).match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : String(t);
  const a = candidate.indexOf('{');
  const b = candidate.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('no JSON object in the reply');
  return JSON.parse(candidate.slice(a, b + 1));
};


// --- tolerant field mapper ------------------------------------
// A vision model handed a raw invoice will often answer in its own
// natural document shape ({from:{name}, line_items:[], total, ...})
// instead of the requested keys. Rather than trust the prompt alone,
// map the shapes we actually see. Only issuer-side keys are ever
// consulted for vendor_name - bill_to / ship_to / customer are the
// PAYER and must never be picked up as the vendor.
const dig = function (o, path) {
  return path.split('.').reduce(function (a, k) {
    return (a && typeof a === 'object') ? a[k] : undefined;
  }, o);
};
const pickStr = function (o, paths) {
  for (const p of paths) {
    const v = dig(o, p);
    if (typeof v === 'string' && v.trim()) return v.trim();
    if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  }
  return '';
};
const pickNum = function (o, paths) {
  for (const p of paths) {
    const n = num(dig(o, p));
    if (n !== null) return n;
  }
  return null;
};
const VENDOR_PATHS = ['vendor_name', 'vendor', 'from.name', 'from.company', 'seller.name',
                      'supplier.name', 'issuer.name', 'company.name', 'from'];
const NUMBER_PATHS = ['invoice_number', 'invoice_no', 'invoiceNumber', 'invoice_id',
                      'invoice.number', 'number'];
const IDATE_PATHS  = ['invoice_date', 'issue_date', 'issued_date', 'issued', 'date'];
const DDATE_PATHS  = ['due_date', 'dueDate', 'payment_due', 'due'];
const TOTAL_PATHS  = ['total_amount', 'balance_due', 'amount_due', 'total_due',
                      'grand_total', 'total'];
const CURR_PATHS   = ['currency', 'currency_code'];

const mapFields = function (x) {
  let desc = pickStr(x, ['description', 'summary', 'notes']);
  if (!desc && Array.isArray(x.line_items)) {
    desc = x.line_items
      .map(function (li) { return li && (li.description || li.name || li.item); })
      .filter(Boolean).join('; ');
  }
  return {
    vendor_name: str(pickStr(x, VENDOR_PATHS)),
    invoice_number: str(pickStr(x, NUMBER_PATHS)),
    invoice_date: str(pickStr(x, IDATE_PATHS)),
    due_date: str(pickStr(x, DDATE_PATHS)),
    total_amount: pickNum(x, TOTAL_PATHS),
    currency: str(pickStr(x, CURR_PATHS)).toUpperCase(),
    description: str(desc).slice(0, 500),
    is_credit_note: x.is_credit_note === true,
  };
};

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const meta = (metas[i] && metas[i].json) || {};

  const base = {
    gmail_message_id: meta.gmail_message_id || '',
    sender_email: meta.sender_email || '',
    subject: meta.subject || '',
    source_type: 'pdf_attachment',
    attachment_filename: meta.attachment_filename || '',
    extraction_method: 'vision_ocr',
  };

  // A failure is NOT an invoice. It is still logged, but it reaches the
  // sheet through is_unreadable, never by pretending to be an invoice.
  const fail = function (why) {
    out.push({
      json: Object.assign({}, base, {
        is_invoice: false,
        not_invoice_reason: '',
        is_unreadable: true,
        extraction_error: why,
        vendor_name: '', invoice_number: '', invoice_date: '', due_date: '',
        total_amount: null, currency: '', description: '', is_credit_note: false,
      }),
    });
  };

  if (meta.ocr_skipped === true) {
    fail(meta.extraction_error || 'PDF binary was not available for OCR');
    continue;
  }

  // BYPASS GUARD - see the matching comment in Standardize Text Result.
  // An item still carrying the base64 payload, with no model response on it,
  // never reached the OCR call. Drop it rather than logging a phantom row.
  if (r.content === undefined && r.choices === undefined && !r.error && !r.type &&
      (r.pdf_base64 !== undefined || r.ocr_system_prompt !== undefined)) {
    continue;
  }

  // Two error shapes reach here: the Anthropic error body, and - now that
  // neverError is off - n8n's own error item after the retries are spent.
  if (r.type === 'error' || r.error) {
    const e = r.error;
    const detail = (typeof e === 'string')
      ? e
      : String((e && (e.message || e.description)) || JSON.stringify(e || {}));
    const kind = (e && (e.type || e.code)) || 'error';
    fail('Vision OCR failed: ' + kind + ' - ' + detail.slice(0, 250));
    continue;
  }

  // --- normalise the two response shapes -----------------------
  let text = '';
  if (Array.isArray(r.content)) {                                  // Anthropic
    text = r.content.filter(function (b) { return b && b.type === 'text'; })
                    .map(function (b) { return b.text; }).join('\n');
  } else if (Array.isArray(r.choices) && r.choices.length) {       // OpenAI-compatible
    text = (r.choices[0].message && r.choices[0].message.content) || '';
  }

  if (!String(text).trim()) { fail('Vision OCR returned no readable content for this file'); continue; }

  let parsed = null;
  try {
    parsed = parseLoose(text);
  } catch (err) {
    fail('Vision OCR returned unparseable output: ' + String(err.message).slice(0, 200));
    continue;
  }

  if (parsed.readable === false) {
    fail('Scan is not legible enough to extract: ' + (parsed.unreadable_reason || 'illegible page'));
    continue;
  }

  const f = mapFields(parsed);

  // The model may answer in its own document shape with no is_invoice
  // flag at all. Absent flag is not the same as "false" - infer it from
  // whether an actual charge was read off the page.
  const explicitFlag = typeof parsed.is_invoice === 'boolean';
  const anyField = Boolean(f.vendor_name || f.invoice_number || f.total_amount !== null || f.invoice_date);

  if (!explicitFlag && !anyField) {
    fail('Vision OCR returned no usable invoice fields');
    continue;
  }

  const isInvoice = explicitFlag
    ? parsed.is_invoice
    : Boolean(f.vendor_name && (f.invoice_number || f.total_amount !== null));

  out.push({
    json: Object.assign({}, base, f, {
      is_invoice: isInvoice,
      not_invoice_reason: isInvoice ? '' : str(parsed.not_invoice_reason),
      is_unreadable: false,
      extraction_error: explicitFlag ? '' : 'Model answered in a non-schema shape; fields were mapped',
    }),
  });
}

return out;

// ============================================================
// Prepare Extraction Input                (Run Once for Each Item)
//
// Node name is still "Prepare Claude Input" so nothing has to be
// rewired, but it now feeds BOTH extractors (Claude and Nemotron).
//
// Three jobs:
//   1. cap the text we pay tokens for
//   2. hold the extraction system prompt in ONE place, so the
//      Information Extractor and the Nemotron HTTP node cannot drift
//   3. give Standardize Text Result a single-output node to index against
// ============================================================
const EXTRACTION_SYSTEM_PROMPT = "You are a strict invoice-extraction assistant for Novus Realty, a property management company.\n\nSTEP 1 - CLASSIFY. Decide whether this document is an actual invoice, bill, statement of charges, or fee note that requests payment for goods or services supplied.\n\nSet is_invoice = true ONLY when the text is itself a demand for payment with charges attached to it.\n\nSet is_invoice = false for anything that merely talks ABOUT invoicing, including:\n- newsletters, team updates and operational announcements, even ones that mention invoices, billing portals or cutover dates\n- automated reminders to update a saved card or payment method\n- payment confirmations, receipts for money already taken, and delivery notices\n- marketing, quotes, proposals and order confirmations\n- portal or account notifications that state that no payment is due\n\nWhen is_invoice is false, put a short reason in not_invoice_reason and leave every other field null.\n\nSTEP 2 - EXTRACT, only when is_invoice is true.\n\nHard rule: BLANK BEATS INVENTED. If a field is not explicitly present in the text, return null. Never derive an invoice number from the subject line, the filename, a PO number, a reference code or an account number. Never estimate a date or an amount. null is always the correct answer for a field the document does not carry.\n\n- vendor_name: the organisation issuing the invoice, that is the party to be paid. Never Novus Realty.\n- invoice_number: exactly as printed. A document may label it Invoice No, Reference, Ref, Factuurnummer or Document No. Use it only when it clearly identifies THIS invoice. If there is no such identifier, return null.\n- invoice_date and due_date: ISO YYYY-MM-DD. Convert \"12 August 2026\", \"12/08/2026\" and \"August 12, 2026\" correctly. Dutch, French and German documents use DAY/MONTH/YEAR ordering, so read them that way. If only a month is given, use the first day of that month. If a date is absent, return null. Do not compute a due date from payment terms.\n- total_amount: the final amount payable, as a plain number, with no currency symbol and no thousands separator. Decide the decimal separator from the document's own convention: \"1.234,56\" is 1234.56 and \"1,234.56\" is also 1234.56. Prefer a line labelled Total, Total Due, Amount Due, Balance Due, Totaal or Te betalen over a subtotal or a VAT-exclusive figure.\n- currency: 3-letter ISO code. $ becomes USD, EUR or euro or a euro sign becomes EUR, GBP or pound becomes GBP. If the document shows no currency at all, return null.\n- description: one short line summarising what is being billed. Do not pad it.\n- is_credit_note: true when the document is a credit note or refund rather than a charge.\n\nReturn every field, using null for anything absent.";

const MAX_CHARS = 12000;
const text = String($json.invoice_text || '');
const truncated = text.length > MAX_CHARS;

const claude_input = [
  'SOURCE: ' + ($json.source_type || 'unknown'),
  'EMAIL SUBJECT: ' + ($json.subject || ''),
  'SENDER: ' + ($json.sender_email || ''),
  'ATTACHMENT: ' + ($json.attachment_filename || 'none'),
  '',
  '--- DOCUMENT TEXT ---',
  truncated ? text.slice(0, MAX_CHARS) + '\n[...truncated...]' : text,
].join('\n');

return {
  json: Object.assign({}, $json, {
    claude_input: claude_input,
    input_truncated: truncated,
    extraction_system_prompt: EXTRACTION_SYSTEM_PROMPT,
  }),
};

// ============================================================
// Standardize Text Result                 (Run Once for ALL Items)
//
// Accepts three response shapes so the extractor is swappable:
//   - n8n Information Extractor -> $json.output
//   - OpenAI-compatible API     -> $json.choices[0].message.content
//   - already-flat JSON         -> $json
// All are 1:1 and order-preserving with Prepare Claude Input.
// ============================================================
const metas = $('Prepare Claude Input').all();

const num = function (v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const str = function (v) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  return (s === '' || /^(null|n\/a|none|unknown|not specified|not stated|not provided)$/i.test(s)) ? '' : s;
};
const parseLoose = function (t) {
  const fenced = String(t).match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : String(t);
  const a = candidate.indexOf('{');
  const b = candidate.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('no JSON object in the reply');
  return JSON.parse(candidate.slice(a, b + 1));
};


// --- tolerant field mapper ------------------------------------
// A vision model handed a raw invoice will often answer in its own
// natural document shape ({from:{name}, line_items:[], total, ...})
// instead of the requested keys. Rather than trust the prompt alone,
// map the shapes we actually see. Only issuer-side keys are ever
// consulted for vendor_name - bill_to / ship_to / customer are the
// PAYER and must never be picked up as the vendor.
const dig = function (o, path) {
  return path.split('.').reduce(function (a, k) {
    return (a && typeof a === 'object') ? a[k] : undefined;
  }, o);
};
const pickStr = function (o, paths) {
  for (const p of paths) {
    const v = dig(o, p);
    if (typeof v === 'string' && v.trim()) return v.trim();
    if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  }
  return '';
};
const pickNum = function (o, paths) {
  for (const p of paths) {
    const n = num(dig(o, p));
    if (n !== null) return n;
  }
  return null;
};
const VENDOR_PATHS = ['vendor_name', 'vendor', 'from.name', 'from.company', 'seller.name',
                      'supplier.name', 'issuer.name', 'company.name', 'from'];
const NUMBER_PATHS = ['invoice_number', 'invoice_no', 'invoiceNumber', 'invoice_id',
                      'invoice.number', 'number'];
const IDATE_PATHS  = ['invoice_date', 'issue_date', 'issued_date', 'issued', 'date'];
const DDATE_PATHS  = ['due_date', 'dueDate', 'payment_due', 'due'];
const TOTAL_PATHS  = ['total_amount', 'balance_due', 'amount_due', 'total_due',
                      'grand_total', 'total'];
const CURR_PATHS   = ['currency', 'currency_code'];

const mapFields = function (x) {
  let desc = pickStr(x, ['description', 'summary', 'notes']);
  if (!desc && Array.isArray(x.line_items)) {
    desc = x.line_items
      .map(function (li) { return li && (li.description || li.name || li.item); })
      .filter(Boolean).join('; ');
  }
  return {
    vendor_name: str(pickStr(x, VENDOR_PATHS)),
    invoice_number: str(pickStr(x, NUMBER_PATHS)),
    invoice_date: str(pickStr(x, IDATE_PATHS)),
    due_date: str(pickStr(x, DDATE_PATHS)),
    total_amount: pickNum(x, TOTAL_PATHS),
    currency: str(pickStr(x, CURR_PATHS)).toUpperCase(),
    description: str(desc).slice(0, 500),
    is_credit_note: x.is_credit_note === true,
  };
};

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const meta = (metas[i] && metas[i].json) || {};

  const base = {
    gmail_message_id: meta.gmail_message_id || '',
    sender_email: meta.sender_email || '',
    subject: meta.subject || '',
    source_type: meta.source_type || 'email_body',
    attachment_filename: meta.attachment_filename || '',
    extraction_method: meta.source_type === 'pdf_attachment' ? 'pdf_text_layer' : 'email_body',
  };

  const fail = function (why) {
    out.push({
      json: Object.assign({}, base, {
        is_invoice: false,
        not_invoice_reason: '',
        is_unreadable: true,
        extraction_error: why,
        vendor_name: '', invoice_number: '', invoice_date: '', due_date: '',
        total_amount: null, currency: '', description: '', is_credit_note: false,
      }),
    });
  };

  if (r.error && r.output === undefined && r.choices === undefined) {
    fail('Extraction failed: ' + String(r.error.message || r.error).slice(0, 250));
    continue;
  }

  // BYPASS GUARD.
  // This item still carries the Prepare Claude Input payload and has no
  // model response on it at all - no output, no choices, no error. It never
  // reached the extractor. That happens when a wire runs from an upstream
  // node directly into this one; n8n creates exactly such a wire on its own
  // when you delete a node from the middle of a chain, because it joins the
  // two neighbours together.
  //
  // The same email is already being handled correctly on the real path, so
  // this is a phantom, not a second invoice. Drop it instead of writing a
  // bogus "no fields extracted" row.
  if (r.output === undefined && r.choices === undefined && !r.error &&
      (r.claude_input !== undefined || r.invoice_text !== undefined ||
       r.extraction_system_prompt !== undefined)) {
    continue;
  }

  let x = null;
  if (r.output !== undefined) {
    x = r.output;
  } else if (Array.isArray(r.choices) && r.choices.length) {
    try {
      x = parseLoose(r.choices[0].message && r.choices[0].message.content);
    } catch (e) {
      fail('Model returned unparseable JSON: ' + String(e.message).slice(0, 200));
      continue;
    }
  } else {
    x = r;
  }

  if (!x || typeof x !== 'object') { fail('Extractor returned no structured output'); continue; }

  const f = mapFields(x);
  const explicitFlag = typeof x.is_invoice === 'boolean';
  const anyField = Boolean(f.vendor_name || f.invoice_number || f.total_amount !== null || f.invoice_date);

  // An extractor that returns NOTHING - no flag and no fields - has
  // malfunctioned. That is not the same as "this is not an invoice",
  // and silently dropping it would hide every invoice in the batch.
  // Surface it as a failed row instead.
  if (!explicitFlag && !anyField) {
    fail('Extractor returned no fields and no is_invoice flag - check the node Text and System Prompt Template fields');
    continue;
  }

  const isInvoice = explicitFlag
    ? x.is_invoice
    : Boolean(f.vendor_name && (f.invoice_number || f.total_amount !== null));

  out.push({
    json: Object.assign({}, base, f, {
      is_invoice: isInvoice,
      not_invoice_reason: isInvoice ? '' : str(x.not_invoice_reason),
      is_unreadable: false,
      extraction_error: '',
    }),
  });
}

return out;

// ============================================================
// Build Unreadable Record                 (Run Once for Each Item)
//
// Corrupt PDFs, unsupported attachments and empty bodies land here.
// No model call is made - that is the cost-aware choice and also the
// only honest one: there is nothing to read. The record is still
// LOGGED so the failure is visible in the sheet instead of vanishing.
//
// is_invoice is FALSE. These are failures, not invoices. They reach
// the sheet on the is_unreadable flag.
// ============================================================
return {
  json: {
    gmail_message_id: $json.gmail_message_id || '',
    sender_email: $json.sender_email || '',
    subject: $json.subject || '',
    source_type: $json.source_type || 'pdf_attachment',
    attachment_filename: $json.attachment_filename || '',
    extraction_method: 'none',

    is_invoice: false,
    not_invoice_reason: '',
    is_unreadable: true,
    extraction_error: $json.extraction_error || 'Attachment could not be read',
    failure_reason: $json.failure_reason || 'unreadable',

    vendor_name: '',
    invoice_number: '',
    invoice_date: '',
    due_date: '',
    total_amount: null,
    currency: '',
    description: '',
    is_credit_note: false,
  },
};

// ============================================================
// Validate Fields & Check Duplicates      (Run Once for ALL Items)
//
// Runs over the WHOLE batch in one pass so that two copies of the same
// invoice arriving in the SAME polling window are caught. The previous
// per-item version could only see rows already written to the sheet,
// which is why TP-01 and TP-05 both got logged when they arrived together.
//
// Three duplicate keys, checked in order:
//   1. gmail_message_id + file reference  (the same email re-processed)
//   2. invoice_number + sender_email      (the same invoice, resent)
//   3. vendor + amount + invoice_date     (resent with no invoice number)
// ============================================================

const norm = function (v) { return (v === null || v === undefined) ? '' : String(v).trim().toLowerCase(); };
const money = function (v) {
  if (v === null || v === undefined || v === '') return '';
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? String(n) : '';
};

// ---- 1. seed the sets from rows already in the sheet ---------
const seenMessage = new Set();
const seenInvoice = new Set();
const seenFingerprint = new Set();
const seenAny = new Set();

let existing = [];
try { existing = $('Fetch All Existing Sheet Records').all(); } catch (e) { existing = []; }

for (const it of existing) {
  const r = it.json || {};
  if (r.error) continue;
  const mid = norm(r['Gmail Message ID']);
  const file = norm(r['File Reference']);
  const inv = norm(r['Invoice Number']);
  const snd = norm(r['Sender Email']);
  const ven = norm(r['Vendor Name']);
  const amt = money(r['Total Amount']);
  const dat = norm(r['Invoice Date']);

  if (mid) seenMessage.add(mid + '|' + file);
  if (inv && snd) seenInvoice.add(inv + '|' + snd);
  if (ven && amt && amt !== '0') seenFingerprint.add(ven + '|' + amt + '|' + dat);

  // last-resort key so a failure row with no vendor, no amount and no
  // invoice number still cannot be appended twice
  const kAnySeed = [mid, file, norm(r['Email Subject']), norm(r['Processing Status'])]
    .filter(Boolean).join('|');
  if (kAnySeed) seenAny.add(kAnySeed);
}

// ---- 2. walk this batch in arrival order --------------------
const out = [];

for (const item of $input.all()) {
  const d = item.json || {};

  const vendor = d.vendor_name || '';
  const invoiceNo = d.invoice_number || '';
  const amount = (d.total_amount === null || d.total_amount === undefined || isNaN(d.total_amount))
    ? null : Number(d.total_amount);
  const currency = d.currency || '';
  const invDate = d.invoice_date || '';
  const dueDate = d.due_date || '';

  const notes = [];
  let status;

  if (d.is_unreadable) {
    status = 'failed';
    notes.push('Failed - ' + (d.extraction_error || 'attachment could not be read'));
    notes.push('No fields extracted - nothing was invented. Open the email and enter it by hand.');
  } else {
    const missing = [];
    if (!vendor) missing.push('vendor_name');
    if (amount === null) missing.push('total_amount');
    if (!currency) missing.push('currency');
    if (!invoiceNo) missing.push('invoice_number');
    if (!invDate && !dueDate) missing.push('invoice_date/due_date');

    if (missing.length === 0) {
      status = 'processed';
    } else if (!vendor && amount === null) {
      // nothing identifying and nothing payable - this row is not usable
      status = 'failed';
      notes.push('Failed - could not extract the fields that identify the invoice. Missing: '
        + missing.join(', ') + '. Nothing was guessed. Open the email and enter it by hand.');
    } else {
      // enough to be useful, but a human has to top it up before payment
      status = 'processed_with_warnings';
      notes.push('Processed with warnings - logged, but incomplete. Missing: '
        + missing.join(', ') + '. Fields left blank are fields the document did not state; '
        + 'nothing was guessed. Fill them in before paying.');
    }

    // format checks - flag, never rewrite
    if (invDate && !/^\d{4}-\d{2}-\d{2}$/.test(invDate)) notes.push('invoice_date is not ISO YYYY-MM-DD');
    if (dueDate && !/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) notes.push('due_date is not ISO YYYY-MM-DD');
    if (currency && !/^[A-Z]{3}$/.test(currency)) notes.push('currency is not a 3-letter ISO code');
    if (amount !== null && amount <= 0) notes.push('total_amount is not positive');
    if (d.is_credit_note) notes.push('Document is a credit note, not a charge');
  }

  // ---- duplicate keys ---------------------------------------
  const mid = norm(d.gmail_message_id);
  const file = norm(d.attachment_filename);
  const kMsg = mid ? mid + '|' + file : '';
  const kInv = (invoiceNo && d.sender_email) ? norm(invoiceNo) + '|' + norm(d.sender_email) : '';
  const amtKey = money(amount);
  const kFp = (vendor && amtKey && amtKey !== '0') ? norm(vendor) + '|' + amtKey + '|' + norm(invDate) : '';

  const kAny = [mid, file, norm(d.subject), status].filter(Boolean).join('|');

  // Stable identity for this invoice. Written to the sheet as Row Key and
  // used by Google Sheets "Append or Update" as the matching column.
  // This is the safety net that makes the write idempotent: a retry after
  // a partial write, a re-run, or n8n splitting a branch into several runs
  // all land on the SAME row instead of adding another one.
  let rowKey;
  if (kInv) rowKey = 'inv:' + kInv;
  else if (kFp) rowKey = 'fp:' + kFp;
  else rowKey = 'msg:' + (mid || norm(d.subject)) + '|' + file;

  let isDup = false;
  let dupReason = '';
  if (kMsg && seenMessage.has(kMsg)) {
    isDup = true; dupReason = 'same Gmail message and file already logged';
  } else if (kInv && seenInvoice.has(kInv)) {
    isDup = true; dupReason = 'invoice ' + invoiceNo + ' from ' + d.sender_email + ' already logged';
  } else if (kFp && seenFingerprint.has(kFp)) {
    isDup = true; dupReason = 'same vendor, amount and date already logged (no invoice number to match on)';
  } else if (kAny && seenAny.has(kAny)) {
    isDup = true; dupReason = 'identical row already logged for this message and file';
  }

  // claim the keys immediately, so the 2nd copy in THIS batch is a duplicate
  if (kMsg) seenMessage.add(kMsg);
  if (kInv) seenInvoice.add(kInv);
  if (kFp) seenFingerprint.add(kFp);
  if (kAny) seenAny.add(kAny);

  out.push({
    json: {
      'Vendor Name': vendor,
      'Sender Email': d.sender_email || '',
      'Invoice Number': invoiceNo,
      'Invoice Date': invDate,
      'Due Date': dueDate,
      'Total Amount': amount === null ? '' : amount,
      'Currency': currency,
      'Description': d.description || '',
      'Source Type': d.source_type || '',
      'File Reference': d.attachment_filename || '',
      'Extraction Method': d.extraction_method || '',
      'Processing Status': status,
      'Error Note': notes.join('; '),
      'Gmail Message ID': d.gmail_message_id || '',
      'Email Subject': d.subject || '',
      'Row Key': rowKey,
      'Processed At': new Date().toISOString(),
      _is_duplicate: isDup,
      _duplicate_reason: dupReason,
      _message_id: d.gmail_message_id || '',
    },
  });
}

return out;

// ============================================================
// Collect Message IDs (Unique)            (Run Once for ALL Items)
//
// Every terminal branch feeds in here:
//   - Append Invoice Row to Sheet  (processed / warnings / failed)
//   - Ignore Duplicate Invoice     (duplicate_skipped)
//   - Ignore Non-Invoice Email     (not_an_invoice)
//
// Jobs:
//   1. Drop items with blank / missing Gmail message ID
//   2. Deduplicate: 1 Gmail call per message (even if multi-attachment)
//   3. Outcome hierarchy: if any attachment was an invoice, the email
//      is treated as an invoice ('processed' beats 'not_an_invoice')
//   4. Pass `is_invoice: boolean` explicitly so 'Was It an Invoice?' works!
// ============================================================
const RANK = { processed: 4, processed_with_warnings: 4, failed: 4, duplicate_skipped: 3, not_an_invoice: 1 };

const best = new Map();

for (const item of $input.all()) {
  const j = item.json || {};
  const id = j._message_id || j['Gmail Message ID'] || j.gmail_message_id || j.message_id || j.id || '';
  if (!id || typeof id !== 'string' || !id.trim()) continue;
  const key = id.trim();

  let outcome = 'processed';
  if (j._is_duplicate === true) {
    outcome = 'duplicate_skipped';
  } else if (j.is_invoice === false && !j['Processing Status']) {
    outcome = 'not_an_invoice';
  } else if (j['Processing Status']) {
    outcome = j['Processing Status'];
  } else if (j.is_invoice === true) {
    outcome = 'processed';
  }

  const rank = RANK[outcome] || 2;
  const prev = best.get(key);
  if (prev && prev.rank >= rank) continue;

  const isInvoice = outcome !== 'not_an_invoice';

  best.set(key, {
    rank: rank,
    json: {
      message_id: key,
      subject: j['Email Subject'] || j.subject || '',
      outcome: outcome,
      is_invoice: isInvoice,
    },
  });
}

return Array.from(best.values()).map(function (e) {
  return { json: e.json };
});
